item.description:
 &lt;h1 id=&#34;Security-Go-—-攻击检测库&#34;&gt;&lt;a href=&#34;#Security-Go-—-攻击检测库&#34; class=&#34;headerlink&#34; title=&#34;Security Go — 攻击检测库&#34;&gt;&lt;/a&gt;Security Go — 攻击检测库&lt;/h1&gt;&lt;p&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/README-EN.md&#34;&gt;English&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;Go 语言编写的攻击检测包，覆盖 &lt;strong&gt;32 个检测器&lt;/strong&gt;、&lt;strong&gt;5 大攻击类别&lt;/strong&gt;、&lt;strong&gt;3 种可插拔存储后端&lt;/strong&gt;。统一接口 + 注册表模式，纯检测库，适配任何 Go HTTP 框架。&lt;/p&gt;
&lt;h2 id=&#34;设计思路&#34;&gt;&lt;a href=&#34;#设计思路&#34; class=&#34;headerlink&#34; title=&#34;设计思路&#34;&gt;&lt;/a&gt;设计思路&lt;/h2&gt;&lt;h3 id=&#34;核心原则&#34;&gt;&lt;a href=&#34;#核心原则&#34; class=&#34;headerlink&#34; title=&#34;核心原则&#34;&gt;&lt;/a&gt;核心原则&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;零依赖检测&lt;/strong&gt; — 所有检测器仅使用 Go 标准库 &lt;code&gt;regexp&lt;/code&gt;，无外部依赖&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;统一接口&lt;/strong&gt; — 每个检测器实现 &lt;code&gt;Detector&lt;/code&gt; 接口（&lt;code&gt;Name()&lt;/code&gt; + &lt;code&gt;Detect()&lt;/code&gt;），通过 &lt;code&gt;Engine&lt;/code&gt; 注册表统一管理&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;预编译正则&lt;/strong&gt; — 所有模式在 &lt;code&gt;var&lt;/code&gt; 初始化时编译，运行时零开销&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;按需配置&lt;/strong&gt; — 注入/协议/数据/文件检测器即插即用；HTTP 校验器需应用自定义配置&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h3 id=&#34;设计架构&#34;&gt;&lt;a href=&#34;#设计架构&#34; class=&#34;headerlink&#34; title=&#34;设计架构&#34;&gt;&lt;/a&gt;设计架构&lt;/h3&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;34&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;35&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;36&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;37&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;38&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;39&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;                      ┌───────────────────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │        security.Engine         │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  ┌─────────────────────────┐  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  │    Detector Registry     │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  │   map[string]Detector    │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  └─────────────────────────┘  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │                               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  Detect(name, input)          │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  DetectAll(input)             │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  DetectRequest(*http.Request) │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      └──────────────┬────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                     │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       ┌─────────────────┬───────────┴───────────┬─────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       │                 │                       │                 │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────▼──────┐   ┌──────▼──────┐   ┌────────────▼────────┐   ┌───▼───────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  injection  │   │  protocol   │   │        data         │   │     file      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   (10 个)   │   │   (9 个)    │   │       (5 个)        │   │    (3 个)     │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│             │   │             │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  xss, sql,  │   │  ssrf, xxe, │   │  deser, csv,        │   │  traversal,   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  command,   │   │  header,    │   │  mail, jwt,         │   │  upload,      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  nosql,     │   │  host,      │   │  proto_poll         │   │  data_leak    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  ldap,      │   │  smuggling, │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  xpath,     │   │  redirect,  │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  jndi, ssi, │   │  cors, ws,  │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  graphql,   │   │  dns_rebind │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  ssti       │   │             │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─────────────┘   └─────────────┘   └─────────────────────┘   └───────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                                                       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       ┌───────────────────────────────────────────────────────────────┤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       │                                                               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────▼──────────┐                                         ┌──────────▼──────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     httpval     │                                         │       storage       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     (5 个)      │                                         │  ┌──────────────┐   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                 │                                         │  │   Backend    │   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  method, size,  │                                         │  │   interface  │   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  type, csrf,    │                                         │  └──┬───┬───┬───┘   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  ip_blacklist   │◄────── 使用 storage.Backend ──────────►│  Memory File Redis │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  (需配置参数)    │                                         │                    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─────────────────┘                                         └────────────────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;数据流&#34;&gt;&lt;a href=&#34;#数据流&#34; class=&#34;headerlink&#34; title=&#34;数据流&#34;&gt;&lt;/a&gt;数据流&lt;/h3&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;HTTP Request&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────────────┐     ┌─────────────────┐     ┌──────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ collectInputs│────▶│  DetectAll()    │────▶│  []*Result   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ URL, Query,  │     │  逐个检测器调用   │     │  聚合结果     │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ Headers,     │     │  Detect(input)  │     │              │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ Cookies      │     └─────────────────┘     └──────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;严重程度分级&#34;&gt;&lt;a href=&#34;#严重程度分级&#34; class=&#34;headerlink&#34; title=&#34;严重程度分级&#34;&gt;&lt;/a&gt;严重程度分级&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;级别&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;th&gt;典型场景&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityLow&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;低风险&lt;/td&gt;
&lt;td&gt;非法 HTTP 方法、Content-Type 不匹配&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityMedium&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;中风险&lt;/td&gt;
&lt;td&gt;CORS 配置问题、开放重定向、GraphQL 内省&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityHigh&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;高风险&lt;/td&gt;
&lt;td&gt;XSS、SQL 注入、SSRF、路径遍历&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityCritical&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;严重&lt;/td&gt;
&lt;td&gt;命令注入、JNDI、SSTI、XXE、数据泄露&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;实现功能&#34;&gt;&lt;a href=&#34;#实现功能&#34; class=&#34;headerlink&#34; title=&#34;实现功能&#34;&gt;&lt;/a&gt;实现功能&lt;/h2&gt;&lt;h3 id=&#34;注入类攻击-10&#34;&gt;&lt;a href=&#34;#注入类攻击-10&#34; class=&#34;headerlink&#34; title=&#34;注入类攻击 (10)&#34;&gt;&lt;/a&gt;注入类攻击 (10)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;检测模式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;XSS&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;script&amp;gt;&lt;/code&gt;、&lt;code&gt;on[a-z]+=&lt;/code&gt; 事件处理器、&lt;code&gt;javascript:&lt;/code&gt; 伪协议、SVG/CSS 注入、&lt;code&gt;eval()&lt;/code&gt;、&lt;code&gt;document.cookie&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SQL 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;UNION SELECT&lt;/code&gt;（含 &lt;code&gt;/**/&lt;/code&gt; 绕过）、&lt;code&gt;sleep/benchmark/pg_sleep&lt;/code&gt;、布尔盲注、&lt;code&gt;information_schema&lt;/code&gt; 枚举、&lt;code&gt;xp_cmdshell&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;命令注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;反引号、&lt;code&gt;$()&lt;/code&gt;、管道符、&lt;code&gt;/dev/tcp&lt;/code&gt;、PHP &lt;code&gt;system/exec/shell_exec&lt;/code&gt;、链式执行 &lt;code&gt;&amp;amp;&amp;amp;&lt;/code&gt; &lt;code&gt;;&lt;/code&gt; `\&lt;/td&gt;
&lt;td&gt;\&lt;/td&gt;
&lt;td&gt;`&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;NoSQL 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;MongoDB &lt;code&gt;$ne&lt;/code&gt; &lt;code&gt;$gt&lt;/code&gt; &lt;code&gt;$regex&lt;/code&gt; &lt;code&gt;$where&lt;/code&gt; 操作符、&lt;code&gt;$func&lt;/code&gt;、JSON 键注入&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;LDAP 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;过滤操作符 `(\&lt;/td&gt;
&lt;td&gt;(&amp;amp;(!&lt;code&gt;、&lt;/code&gt;objectClass=*`、URL 编码绕过&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;XPATH 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;布尔绕过 &lt;code&gt;&amp;#39; or &amp;#39;1&amp;#39;=&amp;#39;1&lt;/code&gt;、&lt;code&gt;string-length()&lt;/code&gt;、&lt;code&gt;count()&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;JNDI/Log4Shell&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;$&amp;#123;jndi:ldap://&lt;/code&gt;、&lt;code&gt;$&amp;#123;lower:j&amp;#125;&lt;/code&gt; 混淆、&lt;code&gt;$&amp;#123;env:&amp;#125;&lt;/code&gt; 环境变量、&lt;code&gt;ldap/rmi/dns&lt;/code&gt; 协议&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SSI 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;!--#exec cmd=&lt;/code&gt;、&lt;code&gt;&amp;lt;!--#include file=&lt;/code&gt;、&lt;code&gt;&amp;lt;!--#echo var=&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;GraphQL 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;__schema&lt;/code&gt;/&lt;code&gt;__type&lt;/code&gt; 内省、深度嵌套 DoS（5层+）、&lt;code&gt;mutation&lt;/code&gt; 检测&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SSTI&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Jinja2 &lt;code&gt;&amp;#123;&amp;#123;&amp;#125;&amp;#125;&lt;/code&gt;、FreeMarker &lt;code&gt;$&amp;#123;&amp;#125;&lt;/code&gt;、ERB &lt;code&gt;&amp;lt;% %&amp;gt;&lt;/code&gt;、Python MRO 遍历、&lt;code&gt;config/self&lt;/code&gt; 访问&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;协议与请求攻击-9&#34;&gt;&lt;a href=&#34;#协议与请求攻击-9&#34; class=&#34;headerlink&#34; title=&#34;协议与请求攻击 (9)&#34;&gt;&lt;/a&gt;协议与请求攻击 (9)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;检测模式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SSRF&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;内网 IP（127/10/172.16/192.168）、&lt;code&gt;169.254.169.254&lt;/code&gt;、IPv6 loopback、&lt;code&gt;gopher/dict/file/ftp&lt;/code&gt; 协议&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;XXE&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;!ENTITY SYSTEM/PUBLIC&lt;/code&gt;、参数实体 &lt;code&gt;%entity;&lt;/code&gt;、DOCTYPE 声明&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;HTTP 头注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;CRLF &lt;code&gt;%0d%0a&lt;/code&gt; / &lt;code&gt;\r\n&lt;/code&gt;、Set-Cookie/Location/Content-Length 注入&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Host 头攻击&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;CRLF Host 注入、&lt;code&gt;X-Forwarded-Host&lt;/code&gt;、&lt;code&gt;X-Original-URL&lt;/code&gt; 投毒&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;请求走私&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Transfer-Encoding/Content-Length 不一致、双重 TE 头、&lt;code&gt;\x0b&lt;/code&gt; 折叠头混淆&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;开放重定向&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;//evil.com&lt;/code&gt; 协议相对 URL、&lt;code&gt;javascript:/data:&lt;/code&gt; 伪协议&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;CORS 绕过&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Origin: null&lt;/code&gt;、&lt;code&gt;Access-Control-Allow-*&lt;/code&gt; 头注入&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;WebSocket 劫持&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Upgrade 头注入、null Origin 绕过、&lt;code&gt;ws://&lt;/code&gt; URL&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;DNS 重绑定&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Host 头内网 IP、localhost、无 TLD 短主机名&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;HTTP-协议层校验-5&#34;&gt;&lt;a href=&#34;#HTTP-协议层校验-5&#34; class=&#34;headerlink&#34; title=&#34;HTTP 协议层校验 (5)&#34;&gt;&lt;/a&gt;HTTP 协议层校验 (5)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;HTTP 方法&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;仅允许 GET/POST/PUT/DELETE/HEAD/OPTIONS/PATCH，其他返回告警&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;请求体大小&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;超过上限（默认 10MB）触发告警&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Content-Type&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;仅允许配置的 MIME 类型白名单&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;CSRF Origin&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;检测跨域请求 Origin 与 Host 是否匹配，支持额外白名单&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;IP 黑名单&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;窗口时间 N 次攻击后自动封禁（默认 5次/60s→封禁15分钟），支持 File/Redis/Memory 存储&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;数据与序列化攻击-5&#34;&gt;&lt;a href=&#34;#数据与序列化攻击-5&#34; class=&#34;headerlink&#34; title=&#34;数据与序列化攻击 (5)&#34;&gt;&lt;/a&gt;数据与序列化攻击 (5)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;检测模式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;PHP 反序列化&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;O:数字:&lt;/code&gt; / &lt;code&gt;C:数字:&lt;/code&gt; 序列化对象、&lt;code&gt;unserialize()&lt;/code&gt;、魔术方法（&lt;code&gt;__wakeup&lt;/code&gt;/&lt;code&gt;__destruct&lt;/code&gt;）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;CSV 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;`=cmd\&lt;/td&gt;
&lt;td&gt;&lt;code&gt;、&lt;/code&gt;@SUM(&lt;code&gt;、&lt;/code&gt;+&lt;code&gt;/&lt;/code&gt;-&lt;code&gt;公式前缀、&lt;/code&gt;HYPERLINK&lt;code&gt;/&lt;/code&gt;DDE`&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;邮件头注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Bcc/Cc/From/To 注入、MIME multipart、boundary 参数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;JWT 攻击&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;alg: none&lt;/code&gt; 绕过、&lt;code&gt;kid&lt;/code&gt; 路径遍历、空签名检测（结构解码分析）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;原型污染&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;__proto__&lt;/code&gt;/&lt;code&gt;constructor&lt;/code&gt; 键、&lt;code&gt;__defineGetter__&lt;/code&gt;/&lt;code&gt;__defineSetter__&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;文件与敏感数据-3&#34;&gt;&lt;a href=&#34;#文件与敏感数据-3&#34; class=&#34;headerlink&#34; title=&#34;文件与敏感数据 (3)&#34;&gt;&lt;/a&gt;文件与敏感数据 (3)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;检测模式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;路径遍历&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;../&lt;/code&gt;、&lt;code&gt;..\\&lt;/code&gt;、&lt;code&gt;php://filter&lt;/code&gt;/&lt;code&gt;php://input&lt;/code&gt;、null 字节、URL 编码绕过、&lt;code&gt;/etc/passwd&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;恶意上传&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;扩展名白名单（15种）+ PHP 标签 &lt;code&gt;&amp;lt;?php&lt;/code&gt;/&lt;code&gt;&amp;lt;?=&lt;/code&gt; 内容扫描&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;数据泄露&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;信用卡号、AWS Access Key、私钥 &lt;code&gt;-----BEGIN&lt;/code&gt;、数据库连接串、API Token、JWT Secret、GitHub PAT&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;存储后端-3&#34;&gt;&lt;a href=&#34;#存储后端-3&#34; class=&#34;headerlink&#34; title=&#34;存储后端 (3)&#34;&gt;&lt;/a&gt;存储后端 (3)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;后端&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Memory&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;sync.Mutex&lt;/code&gt; + map，30s 自动清理过期条目&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;File&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;JSON 文件持久化，Close 时 flush&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Redis&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;独立子模块，Pipeline Incr + TTL，需 &lt;code&gt;go-redis/v9&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;使用说明&#34;&gt;&lt;a href=&#34;#使用说明&#34; class=&#34;headerlink&#34; title=&#34;使用说明&#34;&gt;&lt;/a&gt;使用说明&lt;/h2&gt;&lt;h3 id=&#34;安装&#34;&gt;&lt;a href=&#34;#安装&#34; class=&#34;headerlink&#34; title=&#34;安装&#34;&gt;&lt;/a&gt;安装&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;go get github.com/erikwang2013/security-go&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;快速开始&#34;&gt;&lt;a href=&#34;#快速开始&#34; class=&#34;headerlink&#34; title=&#34;快速开始&#34;&gt;&lt;/a&gt;快速开始&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;package&lt;/span&gt; main&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;fmt&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;github.com/erikwang2013/security-go&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;github.com/erikwang2013/security-go/all&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;main&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;()&lt;/span&gt;&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    e := security.NewEngine()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    all.RegisterAll(e) &lt;span class=&#34;comment&#34;&gt;// 一键注册 27 个零配置检测器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 单个检测&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    r := e.Detect(&lt;span class=&#34;string&#34;&gt;&amp;quot;xss&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;lt;script&amp;gt;alert(1)&amp;lt;/script&amp;gt;&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    fmt.Printf(&lt;span class=&#34;string&#34;&gt;&amp;quot;检测到: %v, 严重程度: %d\n&amp;quot;&lt;/span&gt;, r.Detected, r.Severity)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 全量检测&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _, r := &lt;span class=&#34;keyword&#34;&gt;range&lt;/span&gt; e.DetectAll(&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;#x27; OR &amp;#x27;1&amp;#x27;=&amp;#x27;1&amp;quot;&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        fmt.Printf(&lt;span class=&#34;string&#34;&gt;&amp;quot;[%s] %s\n&amp;quot;&lt;/span&gt;, r.Name, r.Message)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;HTTP-请求检测&#34;&gt;&lt;a href=&#34;#HTTP-请求检测&#34; class=&#34;headerlink&#34; title=&#34;HTTP 请求检测&#34;&gt;&lt;/a&gt;HTTP 请求检测&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;handler&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;(w http.ResponseWriter, r *http.Request)&lt;/span&gt;&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    e := security.NewEngine()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    all.RegisterAll(e)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _, result := &lt;span class=&#34;keyword&#34;&gt;range&lt;/span&gt; e.DetectRequest(r) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; result.Detected &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            log.Printf(&lt;span class=&#34;string&#34;&gt;&amp;quot;攻击检测: [%s] %s&amp;quot;&lt;/span&gt;, result.Name, result.Message)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;HTTP-校验器配置&#34;&gt;&lt;a href=&#34;#HTTP-校验器配置&#34; class=&#34;headerlink&#34; title=&#34;HTTP 校验器配置&#34;&gt;&lt;/a&gt;HTTP 校验器配置&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 方法校验&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(&amp;amp;httpval.Method&amp;#123;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 请求体大小限制&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(httpval.NewBodySize(&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt; * &lt;span class=&#34;number&#34;&gt;1024&lt;/span&gt; * &lt;span class=&#34;number&#34;&gt;1024&lt;/span&gt;)) &lt;span class=&#34;comment&#34;&gt;// 5MB&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// Content-Type 白名单&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(httpval.NewContentType([]&lt;span class=&#34;type&#34;&gt;string&lt;/span&gt;&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;application/json&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;application/x-www-form-urlencoded&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// CSRF Origin 检查&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(&amp;amp;httpval.CSRFOrigin&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Host: &lt;span class=&#34;string&#34;&gt;&amp;quot;example.com&amp;quot;&lt;/span&gt;, AllowList: []&lt;span class=&#34;type&#34;&gt;string&lt;/span&gt;&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;quot;api.example.com&amp;quot;&lt;/span&gt;&amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// IP 黑名单（自动封禁：5次/60s → 封禁15分钟）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mem := storage.NewMemory()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;defer&lt;/span&gt; mem.Close()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bl := httpval.NewIPBlacklist(mem)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(bl)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 攻击发生时记录&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;blocked, _ := bl.RecordAttack(clientIP)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;自定义检测器&#34;&gt;&lt;a href=&#34;#自定义检测器&#34; class=&#34;headerlink&#34; title=&#34;自定义检测器&#34;&gt;&lt;/a&gt;自定义检测器&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;type&lt;/span&gt; MyDetector &lt;span class=&#34;keyword&#34;&gt;struct&lt;/span&gt;&amp;#123;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;params&#34;&gt;(d *MyDetector)&lt;/span&gt;&lt;/span&gt; Name() &lt;span class=&#34;type&#34;&gt;string&lt;/span&gt; &amp;#123; &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;my_detector&amp;quot;&lt;/span&gt; &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;params&#34;&gt;(d *MyDetector)&lt;/span&gt;&lt;/span&gt; Detect(input &lt;span class=&#34;type&#34;&gt;string&lt;/span&gt;) *security.Result &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &amp;amp;security.Result&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        Name: &lt;span class=&#34;string&#34;&gt;&amp;quot;my_detector&amp;quot;&lt;/span&gt;, Detected: strings.Contains(input, &lt;span class=&#34;string&#34;&gt;&amp;quot;evil&amp;quot;&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        Severity: security.SeverityHigh, Message: &lt;span class=&#34;string&#34;&gt;&amp;quot;检测到恶意内容&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(&amp;amp;MyDetector&amp;#123;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;相关文档&#34;&gt;&lt;a href=&#34;#相关文档&#34; class=&#34;headerlink&#34; title=&#34;相关文档&#34;&gt;&lt;/a&gt;相关文档&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/docs/superpowers/specs/2026-07-29-attack-detection-design.md&#34;&gt;设计规范&lt;/a&gt; — 包结构、核心 API、检测器目录&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/docs/superpowers/plans/2026-07-29-attack-detection-plan.md&#34;&gt;实施计划&lt;/a&gt; — 分步任务计划与实施偏差对照&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/docs/superpowers/reports/2026-07-29-code-review-report.md&#34;&gt;代码审查报告&lt;/a&gt; — Bug 修复、测试覆盖、架构评估&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;hr&gt;
&lt;p&gt;Copyright (c) 2026 erik &lt;a href=&#34;&amp;#109;&amp;#x61;&amp;#x69;&amp;#108;&amp;#x74;&amp;#111;&amp;#x3a;&amp;#101;&amp;#x72;&amp;#x69;&amp;#x6b;&amp;#x40;&amp;#101;&amp;#114;&amp;#105;&amp;#x6b;&amp;#46;&amp;#120;&amp;#x79;&amp;#x7a;&#34;&gt;&amp;#101;&amp;#x72;&amp;#x69;&amp;#x6b;&amp;#x40;&amp;#101;&amp;#114;&amp;#105;&amp;#x6b;&amp;#46;&amp;#120;&amp;#x79;&amp;#x7a;&lt;/a&gt; — &lt;a href=&#34;https://erik.xyz&#34;&gt;https://erik.xyz&lt;/a&gt;&lt;/p&gt;

 &lt;p&gt;需求是这样的：&lt;br&gt;有个外部app给我们小程序做推广，在他们那领取优惠券码。然后到我们小程序领取优惠券，使用优惠券下单。同时，需要我们推送订单。还要接受他们那变更优惠券的状态。&lt;br&gt;&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;&lt;br&gt;思路图如下：&lt;br&gt;&lt;img src=&#34;/img/202211/20221116094358.jpg&#34; alt=&#34;思路图&#34; title=&#34;思路图&#34;&gt;&lt;/p&gt;
&lt;p&gt;那么，根据上面的思路。我这需要开发三个接口&lt;/p&gt;
&lt;p&gt;1.优惠券列表&lt;/p&gt;
&lt;p&gt;第三方调用接口，获取优惠券信息&lt;/p&gt;
&lt;p&gt;2.优惠券状态变更&lt;/p&gt;
&lt;p&gt;第三方调用变更优惠券状态&lt;/p&gt;
&lt;p&gt;3.优惠券订单推送&lt;/p&gt;
&lt;p&gt;第三方提供url，我这边根据使用优惠券产生的订单来推送订单信息&lt;/p&gt;
&lt;p&gt;首先，设计一个开放应用表，主要存储应用id、应用秘钥，如图&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/img/202211/20221116102006.jpg&#34; alt=&#34;应用表设计&#34; title=&#34;应用表设计&#34;&gt;&lt;/p&gt;
&lt;p&gt;要给数据做个签名以及重要数据做加密处理&lt;/p&gt;
&lt;p&gt;签名就用常规的格式（也可以自己改动格式）:时间戳+应用秘钥+传输数据&lt;br&gt;按照上面的格式md5一下，然后再转码成base64。时间戳和签名要放在请求头传输。如图&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;/img/202211/20221116102258.jpg&#34; alt=&#34;签名代码&#34; title=&#34;签名代码&#34;&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;func CouponSigin(appId, jsonData string, sid int, def ...string) (*string, *string, *string, error) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    openApp, err := GetStoreApp(appId, sid, 0)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    if err != nil &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        logs.Error(&amp;quot;获取应用失败&amp;quot;, err)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        return nil, nil, nil, err&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    apiKey := openApp.ApiOne&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    getTime := Util.Int64ToString(time.Now().UnixNano())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    if len(def) &amp;gt; 0 &amp;amp;&amp;amp; len(def[0]) &amp;gt; 0 &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        getTime = def[0]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    strData := getTime + apiKey + jsonData + getTime&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    md := md5.New()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    md.Write([]byte(strData))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    md5Str := hex.EncodeToString(md.Sum(nil))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    SystemSign := base64.StdEncoding.EncodeToString([]byte(md5Str))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    logs.Error(&amp;quot;==签名==&amp;quot;, SystemSign)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    logs.Error(&amp;quot;==时间戳==&amp;quot;, getTime)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    return &amp;amp;SystemSign, &amp;amp;getTime, &amp;amp;apiKey, nil&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;加解密就用常规的aes加密，自己用应用秘钥加密，这里不多讲了，很常见的。&lt;/p&gt;
&lt;p&gt;到这里基础弄好了。&lt;/p&gt;
&lt;p&gt;我们开发优惠券列表、变更优惠券状态、推送优惠券订单就可以通过签名校验数据，同时敏感数据就加密&lt;/p&gt;

 &lt;p&gt;beego中数据库分页&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;  func PageDB(limit int, page int, count int64) (int, int) &amp;#123;
      pageSetNum := limit // 每页条数

      pageCount := math.Ceil((float64(count)) / (float64(pageSetNum))) // 总页数
      pageNum := page                                                  // 当前页码

      if pageNum &amp;gt; int(pageCount) &amp;#123; // 如果传入的页码超出范围
          pageNum = int(pageCount)
      &amp;#125;
      offset := pageSetNum * (pageNum - 1)
      if offset &amp;lt; 0 &amp;#123;
          offset = 0
      &amp;#125;
      return pageSetNum, offset
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;

 &lt;ul&gt;
&lt;li&gt;韵达签名&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code&gt;  func YunDaSign(structData interface&amp;#123;&amp;#125;) ([]byte, string, string) &amp;#123;
      jsonData, _ := json.Marshal(structData)
      appKey := &amp;quot;你的key&amp;quot;
      appSecret := &amp;quot;你的秘钥&amp;quot;
      newStr := string(jsonData) + &amp;quot;_&amp;quot; + appSecret
      md := md5.New()
      md.Write([]byte(newStr))
      md5Str := hex.EncodeToString(md.Sum(nil))
      return jsonData, appKey, md5Str
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;ul&gt;
&lt;li&gt;京东签名&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code&gt;  func JdSigin(body string, path string) (string, string, string, string, string) &amp;#123;
      appKey := &amp;quot;你的key&amp;quot;
      appSecret := &amp;quot;你的秘钥&amp;quot;
      accessToken := &amp;quot;你的token&amp;quot;
      timestamp := Util.GetDate()
      algorithm := &amp;quot;md5-salt&amp;quot;
      content := strings.Join([]string&amp;#123;
          appSecret,
          &amp;quot;access_token&amp;quot;, accessToken,
          &amp;quot;app_key&amp;quot;, appKey,
          &amp;quot;method&amp;quot;, path,
          &amp;quot;param_json&amp;quot;, body,
          &amp;quot;timestamp&amp;quot;, timestamp,
          &amp;quot;v&amp;quot;, &amp;quot;2.0&amp;quot;,
          appSecret,
      &amp;#125;, &amp;quot;&amp;quot;)

      sign, err := Sign(algorithm, []byte(content), appSecret)
      if err != nil &amp;#123;
          panic(err)
      &amp;#125;
      return sign, appKey, accessToken, timestamp, algorithm
  &amp;#125;

  func Sign(algorithm string, data []byte, secret string) (string, error) &amp;#123;
      if algorithm == &amp;quot;md5-salt&amp;quot; &amp;#123;
          h := md5.New()
          if _, err := h.Write(data); err != nil &amp;#123;
              return &amp;quot;&amp;quot;, err
          &amp;#125;
          return fmt.Sprintf(&amp;quot;%x&amp;quot;, h.Sum(nil)), nil
      &amp;#125; else if algorithm == &amp;quot;HMacMD5&amp;quot; &amp;#123;
          h := hmac.New(md5.New, []byte(secret))
          if _, err := h.Write(data); err != nil &amp;#123;
              return &amp;quot;&amp;quot;, err
          &amp;#125;
          return base64.StdEncoding.EncodeToString(h.Sum(nil)), nil
      &amp;#125; else if algorithm == &amp;quot;HMacSHA1&amp;quot; &amp;#123;
          h := hmac.New(sha1.New, []byte(secret))
          if _, err := h.Write(data); err != nil &amp;#123;
              return &amp;quot;&amp;quot;, err
          &amp;#125;
          return base64.StdEncoding.EncodeToString(h.Sum(nil)), nil
      &amp;#125; else if algorithm == &amp;quot;HMacSHA256&amp;quot; &amp;#123;
          h := hmac.New(sha256.New, []byte(secret))
          if _, err := h.Write(data); err != nil &amp;#123;
              return &amp;quot;&amp;quot;, err
          &amp;#125;
          return base64.StdEncoding.EncodeToString(h.Sum(nil)), nil
      &amp;#125; else if algorithm == &amp;quot;HMacSHA512&amp;quot; &amp;#123;
          h := hmac.New(sha512.New, []byte(secret))
          if _, err := h.Write(data); err != nil &amp;#123;
              return &amp;quot;&amp;quot;, err
          &amp;#125;
          return base64.StdEncoding.EncodeToString(h.Sum(nil)), nil
      &amp;#125;
      return &amp;quot;&amp;quot;, fmt.Errorf(&amp;quot;algorithm %s not supported yet&amp;quot;, algorithm)
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;

 &lt;pre&gt;&lt;code&gt;func PKCS7Padding(ciphertext []byte, blockSize int) []byte &amp;#123;
    padding := blockSize - len(ciphertext)%blockSize
    //Repeat()函数的功能是把切片[]byte&amp;#123;byte(padding)&amp;#125;复制padding个，然后合并成新的字节切片返回
    padtext := bytes.Repeat([]byte&amp;#123;byte(padding)&amp;#125;, padding)
    return append(ciphertext, padtext...)
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;pre&gt;&lt;code&gt;  //填充的反向操作，删除填充字符串
  func PKCS7UnPadding(origData []byte) ([]byte, error) &amp;#123;
      //获取数据长度
      length := len(origData)
      if length == 0 &amp;#123;
          return nil, errors.New(&amp;quot;加密字符串错误！&amp;quot;)
      &amp;#125; else &amp;#123;
          //获取填充字符串长度
          unpadding := int(origData[length-1])
          //截取切片，删除填充字节，并且返回明文
          return origData[:(length - unpadding)], nil
      &amp;#125;
  &amp;#125;

  //实现加密
  func AesEcrypt(origData []byte, key []byte) ([]byte, error) &amp;#123;
      //创建加密算法实例
      block, err := aes.NewCipher(key)
      if err != nil &amp;#123;
          return nil, err
      &amp;#125;
      //获取块的大小
      blockSize := block.BlockSize()
      //对数据进行填充，让数据长度满足需求
      origData = PKCS7Padding(origData, blockSize)
      //采用AES加密方法中CBC加密模式
      blocMode := cipher.NewCBCEncrypter(block, key[:blockSize])
      crypted := make([]byte, len(origData))
      //执行加密
      blocMode.CryptBlocks(crypted, origData)
      return crypted, nil
  &amp;#125;

  //实现解密
  func AesDeCrypt(cypted []byte, key []byte) ([]byte, error) &amp;#123;
      //创建加密算法实例
      block, err := aes.NewCipher(key)
      if err != nil &amp;#123;
          return nil, err
      &amp;#125;
      //获取块大小
      blockSize := block.BlockSize()
      //创建加密客户端实例
      blockMode := cipher.NewCBCDecrypter(block, key[:blockSize])
      origData := make([]byte, len(cypted))
      //这个函数也可以用来解密
      blockMode.CryptBlocks(origData, cypted)
      //去除填充字符串
      origData, err = PKCS7UnPadding(origData)
      if err != nil &amp;#123;
          return nil, err
      &amp;#125;
      return origData, err
  &amp;#125;

  //加密base64
  func EnPwdCode(pwd []byte) (string, error) &amp;#123;
      result, err := AesEcrypt(pwd, getKey())
      if err != nil &amp;#123;
          return &amp;quot;&amp;quot;, err
      &amp;#125;
      return base64.StdEncoding.EncodeToString(result), err
  &amp;#125;

  //解密
  func DePwdCode(pwd string) ([]byte, error) &amp;#123;
      //解密base64字符串
      pwdByte, err := base64.StdEncoding.DecodeString(pwd)
      if err != nil || len(pwdByte) &amp;lt;= 0 &amp;#123;
          return nil, err
      &amp;#125;
      //执行AES解密
      return AesDeCrypt(pwdByte, getKey())
  &amp;#125;

  //加密base64
  func EnPwdUserCode(pwd []byte) (string, error) &amp;#123;
      result, err := AesEcrypt(pwd, getUserKey())
      if err != nil &amp;#123;
          return &amp;quot;&amp;quot;, err
      &amp;#125;
      return base64.StdEncoding.EncodeToString(result), err
  &amp;#125;

  //解密
  func DePwdUserCode(pwd string) ([]byte, error) &amp;#123;
      //解密base64字符串
      pwdByte, err := base64.StdEncoding.DecodeString(pwd)
      if err != nil || len(pwdByte) &amp;lt;= 0 &amp;#123;
          return nil, err
      &amp;#125;
      //执行AES解密
      return AesDeCrypt(pwdByte, getUserKey())
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;

 &lt;p&gt;一个简单但是非常实用的pdf生成器！&lt;/p&gt;
&lt;p&gt;安装：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;go get github.com/jung-kurt/gofpdf
&lt;/code&gt;&lt;/pre&gt;&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;p&gt;代码：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;package main

import (
    &amp;quot;github.com/jung-kurt/gofpdf&amp;quot;
)

func main() &amp;#123;
    err := GeneratePdf(&amp;quot;hello.pdf&amp;quot;)
    if err != nil &amp;#123;
        panic(err)
    &amp;#125;
&amp;#125;

func GeneratePdf(filename string) error &amp;#123;
  pdf := gofpdf.New(&amp;quot;P&amp;quot;, &amp;quot;mm&amp;quot;, &amp;quot;A4&amp;quot;, &amp;quot;&amp;quot;)
  pdf.AddPage()
  pdf.SetFont(&amp;quot;Arial&amp;quot;, &amp;quot;B&amp;quot;, 16)
  pdf.CellFormat(190, 7, &amp;quot;Welcome to topgoer.com&amp;quot;, &amp;quot;0&amp;quot;, 0, &amp;quot;CM&amp;quot;, false, 0, &amp;quot;&amp;quot;)

  pdf.ImageOptions(
      &amp;quot;topgoer.png&amp;quot;,
      80, 20,
      0, 0,
      false,
      gofpdf.ImageOptions&amp;#123;ImageType: &amp;quot;PNG&amp;quot;, ReadDpi: true&amp;#125;,
      0,
      &amp;quot;&amp;quot;,
  )

  return pdf.OutputFileAndClose(filename)
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;

 &lt;pre&gt;&lt;code&gt;package main

import (
    &amp;quot;encoding/json&amp;quot;
    &amp;quot;net/http&amp;quot;
)

func main() &amp;#123;
    http.HandleFunc(&amp;quot;/&amp;quot;, ExampleHandler)
    if err := http.ListenAndServe(&amp;quot;:8080&amp;quot;, nil); err != nil &amp;#123;
        panic(err)
    &amp;#125;
&amp;#125;

func ExampleHandler(w http.ResponseWriter, r *http.Request) &amp;#123;
    w.Header().Add(&amp;quot;Content-Type&amp;quot;, &amp;quot;application/json&amp;quot;)
    resp, _ := json.Marshal(map[string]string&amp;#123;
        &amp;quot;ip&amp;quot;: GetIP(r),
    &amp;#125;)
    w.Write(resp)
&amp;#125;

func GetIP(r *http.Request) string &amp;#123;
    forwarded := r.Header.Get(&amp;quot;X-FORWARDED-FOR&amp;quot;)
    if forwarded != &amp;quot;&amp;quot; &amp;#123;
        return forwarded
    &amp;#125;
    return r.RemoteAddr
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;

 &lt;p&gt;限流器是后台服务中的非常重要的组件，可以用来限制请求速率，保护服务，以免服务过载。 限流器的实现方法有很多种，例如滑动窗口法、Token Bucket、Leaky Bucket等。&lt;/p&gt;
&lt;p&gt;其实golang标准库中就自带了限流算法的实现，即golang.org/x/time/rate。 该限流器是基于Token Bucket(令牌桶)实现的。&lt;/p&gt;
&lt;p&gt;简单来说，令牌桶就是想象有一个固定大小的桶，系统会以恒定速率向桶中放Token，桶满则暂时不放。 而用户则从桶中取Token，如果有剩余Token就可以一直取。如果没有剩余Token，则需要等到系统中被放置了Token才行。&lt;br&gt;&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;&lt;br&gt;本文则主要集中介绍下该组件的具体使用方法：&lt;/p&gt;
&lt;p&gt;我们可以使用以下方法构造一个限流器对象：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;limiter := NewLimiter(10, 1);
&lt;/code&gt;&lt;/pre&gt;&lt;p&gt;这里有两个参数：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;第一个参数是r Limit。代表每秒可以向Token桶中产生多少token。Limit实际上是float64的别名。&lt;/li&gt;
&lt;li&gt;第二个参数是b int。b代表Token桶的容量大小。 那么，对于以上例子来说，其构造出的限流器含义为，其令牌桶大小为1, 以每秒10个Token的速率向桶中放置Token。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;除了直接指定每秒产生的Token个数外，还可以用Every方法来指定向Token桶中放置Token的间隔，例如：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;limit := Every(100 * time.Millisecond);
limiter := NewLimiter(limit, 1);
&lt;/code&gt;&lt;/pre&gt;&lt;p&gt;以上就表示每100ms往桶中放一个Token。本质上也就是一秒钟产生10个。&lt;/p&gt;
&lt;p&gt;Limiter提供了三类方法供用户消费Token，用户可以每次消费一个Token，也可以一次性消费多个Token。 而每种方法代表了当Token不足时，各自不同的对应手段。&lt;/p&gt;
&lt;p&gt; Wait/WaitN &lt;/p&gt;
&lt;pre&gt;&lt;code&gt;func (lim *Limiter) Wait(ctx context.Context) (err error)
func (lim *Limiter) WaitN(ctx context.Context, n int) (err error)
&lt;/code&gt;&lt;/pre&gt;&lt;p&gt;Wait实际上就是WaitN(ctx,1)。&lt;/p&gt;
&lt;p&gt;当使用Wait方法消费Token时，如果此时桶内Token数组不足(小于N)，那么Wait方法将会阻塞一段时间，直至Token满足条件。如果充足则直接返回。&lt;/p&gt;
&lt;p&gt;这里可以看到，Wait方法有一个context参数。 我们可以设置context的Deadline或者Timeout，来决定此次Wait的最长时间。&lt;/p&gt;
&lt;p&gt;Allow/AllowN&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;func (lim *Limiter) Allow() bool
func (lim *Limiter) AllowN(now time.Time, n int) bool
&lt;/code&gt;&lt;/pre&gt;&lt;p&gt;Allow实际上就是AllowN(time.Now(),1)。&lt;/p&gt;
&lt;p&gt;AllowN方法表示，截止到某一时刻，目前桶中数目是否至少为n个，满足则返回true，同时从桶中消费n个token。 反之返回不消费Token，false。&lt;/p&gt;
&lt;p&gt;通常对应这样的线上场景，如果请求速率过快，就直接丢到某些请求。&lt;/p&gt;
&lt;p&gt; Reserve/ReserveN&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;func (lim *Limiter) Reserve() *Reservation
func (lim *Limiter) ReserveN(now time.Time, n int) *Reservation
&lt;/code&gt;&lt;/pre&gt;&lt;p&gt;Reserve相当于ReserveN(time.Now(), 1)。&lt;/p&gt;
&lt;p&gt;ReserveN的用法就相对来说复杂一些，当调用完成后，无论Token是否充足，都会返回一个Reservation*对象。&lt;/p&gt;
&lt;p&gt;你可以调用该对象的Delay()方法，该方法返回了需要等待的时间。如果等待时间为0，则说明不用等待。 必须等到等待时间之后，才能进行接下来的工作。&lt;/p&gt;
&lt;p&gt;或者，如果不想等待，可以调用Cancel()方法，该方法会将Token归还。&lt;/p&gt;
&lt;p&gt;举一个简单的例子，我们可以这么使用Reserve方法。&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;r := lim.Reserve()
f !r.OK() &amp;#123;
    // Not allowed to act! Did you remember to set lim.burst to be &amp;gt; 0 ?
    return
&amp;#125;
time.Sleep(r.Delay())
Act() // 执行相关逻辑
&lt;/code&gt;&lt;/pre&gt;&lt;p&gt; 动态调整速率&lt;/p&gt;
&lt;p&gt;Limiter支持可以调整速率和桶大小：&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;SetLimit(Limit) 改变放入Token的速率
SetBurst(int) 改变Token桶大小
&lt;/code&gt;&lt;/pre&gt;&lt;p&gt;有了这两个方法，可以根据现有环境和条件，根据我们的需求，动态的改变Token桶大小和速率&lt;/p&gt;
&lt;p&gt;实例代码&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;package main

import (
    &amp;quot;context&amp;quot;
    &amp;quot;log&amp;quot;
    &amp;quot;time&amp;quot;

    &amp;quot;golang.org/x/time/rate&amp;quot;
)

//limit表示每秒产生token数，buret最多存token数
//Allow判断当前是否可以取到token
//Wait阻塞等待知道取到token
//Reserve返回等待时间，再去取token

func main() &amp;#123;
    l := rate.NewLimiter(1, 5)
    log.Println(l.Limit(), l.Burst())
    for i := 0; i &amp;lt; 100; i++ &amp;#123;
        //阻塞等待直到，取到一个token
        log.Println(&amp;quot;before Wait&amp;quot;)
        c, _ := context.WithTimeout(context.Background(), time.Second*2)
        if err := l.Wait(c); err != nil &amp;#123;
            log.Println(&amp;quot;limiter wait err:&amp;quot; + err.Error())
        &amp;#125;
        log.Println(&amp;quot;after Wait&amp;quot;)

        //返回需要等待多久才有新的token,这样就可以等待指定时间执行任务
        r := l.Reserve()
        log.Println(&amp;quot;reserve Delay:&amp;quot;, r.Delay())

        //判断当前是否可以取到token
        a := l.Allow()
        log.Println(&amp;quot;Allow:&amp;quot;, a)
    &amp;#125;
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;

 &lt;p&gt;go中我们往往要对变量分配内存，那么分配内存有两中方式分别是new和make。查了一些资料，顺便看我开发中用的几个地方。其实，很好理解。&lt;/p&gt;
&lt;p&gt;new分配中内存，不做初始化，也就是不能直接赋值，必须初始化后才能赋值。&lt;/p&gt;
&lt;p&gt;make分配好内存且已经&lt;/p&gt;

 &lt;p&gt;在go中往redis的hash写数据的时候遇到了结构体数组写入时无法写入，看了看写入数据要求是map[string]interface，而我的是struct。因此，无法写入的。&lt;br&gt;那么就是转格式呗&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;type order struct&amp;#123;
    Id int64 `json:&amp;quot;id&amp;quot;`
    orderSn int64 `json:&amp;quot;order_sn&amp;quot;`          
&amp;#125;

orders:=order&amp;#123;
    Id:2022032034566
    OrderSn:20220320122444
&amp;#125;

jsonData,_:=json.Marshal(orders)

var redisData map[string]interface&amp;#123;&amp;#125;

json.Unmarshal([]byte(jsonData),&amp;amp;redisData)

log.Info(redisData)
&lt;/code&gt;&lt;/pre&gt;&lt;p&gt;以上就是转化过程。&lt;/p&gt;
